    Mockito.when(bundleContext.registerService(Mockito.eq(ConfigurationAdmin.class), Mockito.any(ServiceFactory.class), (Dictionary) Mockito.any())).thenReturn(Mockito.mock(ServiceRegistration.class));
    final ExtPersistenceManager epm = Mockito.mock(ExtPersistenceManager.class);
