    assertEquals("Original should not be modified", 1, l.size());
    l.set(0, -1.0);
    assertEquals(2, s.size());
    assertTrue(s.contains(null));
    assertTrue(s.contains(f3));
    assertFalse(s.contains(f2));
    assertFalse(s.contains(f1));
}

