    Map<String, MyDTO3> nestedMap = converted.dtoMap;
    // Check iteration order is preserved by iterating
    int i = 0;
    for (Iterator<Map.Entry<String, MyDTO3>> it = nestedMap.entrySet().iterator(); it.hasNext(); i++) {
