@Test
public void testServletOrdering() throws InvalidSyntaxException {
    final ServletHandler h1 = createServletHandler(1L, 0, "/foo");
    reg.addServlet(h1);
    final ServletHandler h2 = createServletHandler(2L, 0, "/foo/*");
    reg.addServlet(h2);
    final ServletHandler h3 = createServletHandler(3L, 0, "/foo/rsrc");
    reg.addServlet(h3);
    final ServletHandler h4 = createServletHandler(4L, 0, "/foo/rsrc/*");
    reg.addServlet(h4);
    final ServletHandler h5 = createServletHandler(5L, 0, "/other");
    reg.addServlet(h5);
    PathResolution pr = null;
    pr = reg.resolve("/foo");
    assertNotNull(pr);
    assertEquals("/foo", pr.patterns[0]);
    assertEquals(h1, pr.handler);
    pr = reg.resolve("/fool");
    assertNull(pr);
    pr = reg.resolve("/foo/bar");
    assertEquals("/foo", pr.patterns[0]);
    assertEquals(h1, pr.handler);
    pr = reg.resolve("/foo/rsrc");
    assertEquals("/foo/rsrc", pr.patterns[0]);
    assertEquals(h3, pr.handler);
    pr = reg.resolve("/foo/rsrc/some");
    assertEquals("/foo/rsrc", pr.patterns[0]);
    assertEquals(h3, pr.handler);
    pr = reg.resolve("/other");
    assertEquals("/other", pr.patterns[0]);
    assertEquals(h5, pr.handler);
    pr = reg.resolve("/other/bla");
    assertEquals("/other", pr.patterns[0]);
    assertEquals(h5, pr.handler);
    // cleanup
    reg.removeServlet(h1.getServletInfo(), true);
    reg.removeServlet(h2.getServletInfo(), true);
    reg.removeServlet(h3.getServletInfo(), true);
    reg.removeServlet(h4.getServletInfo(), true);
    reg.removeServlet(h5.getServletInfo(), true);
}

@Test
public void ordering() {
    assertEquals(expected, signum(testInfo.compareTo(other)));
    if (expected != 0) {
        final List<AbstractInfo> list = new ArrayList<AbstractInfo>();
        list.add(testInfo);
        list.add(other);
        Collections.sort(list);
        if (expected == -1) {
            assertEquals(testInfo, list.get(0));
            assertEquals(other, list.get(1));
        } else {
            assertEquals(testInfo, list.get(1));
            assertEquals(other, list.get(0));
        }
    }
}

@Test
public void orderingSymetry() {
    assertTrue(signum(testInfo.compareTo(other)) == -signum(other.compareTo(testInfo)));
}

@Test
public void orderingTransitivity() {
    assertTrue(testInfo.compareTo(other) >= 0);
    TestInfo three = new TestInfo(0, 0);
    // three falls in between the two other points
    if (testInfo.compareTo(three) >= 0 && three.compareTo(other) >= 0) {
        assertTrue(testInfo.compareTo(other) >= 0);
    } else // three falls below the two other points
    if (testInfo.compareTo(other) >= 0 && other.compareTo(three) >= 0) {
        assertTrue(testInfo.compareTo(three) >= 0);
    } else // three falls above the two other points
    if (three.compareTo(testInfo) >= 0 && testInfo.compareTo(other) >= 0) {
        assertTrue(three.compareTo(other) >= 0);
    } else {
        fail("Since testInfo >= other, one of the above cases must match");
    }
}

