@Test
public void testTrackerOrdering() throws Exception {
    final BundleContext bc = mock(BundleContext.class);
    final CustomizerWrapper wrapper = new CustomizerWrapper();
    final List<String> result = new ArrayList<>();
    final LoadBalancerCustomizerFactoryTracker tracker = new LoadBalancerCustomizerFactoryTracker(bc, wrapper);
    wrapper.customize(null, null, null);
    assertTrue(result.isEmpty());
    final ServiceReference<LoadBalancerCustomizerFactory> refA = create(bc, result, 5, "A");
    final ServiceReference<LoadBalancerCustomizerFactory> refB = create(bc, result, 15, "B");
    final ServiceReference<LoadBalancerCustomizerFactory> refC = create(bc, result, 25, "C");
    // just A
    tracker.addingService(refA);
    wrapper.customize(null, null, null);
    assertEquals(1, result.size());
    assertEquals("A", result.get(0));
    result.clear();
    // add B, B is highest
    tracker.addingService(refB);
    wrapper.customize(null, null, null);
    assertEquals(1, result.size());
    assertEquals("B", result.get(0));
    result.clear();
    // add C, C is highest
    tracker.addingService(refC);
    wrapper.customize(null, null, null);
    assertEquals(1, result.size());
    assertEquals("C", result.get(0));
    result.clear();
    // remove B, C is still highest
    tracker.removedService(refB, refB);
    wrapper.customize(null, null, null);
    assertEquals(1, result.size());
    assertEquals("C", result.get(0));
    result.clear();
    // remove C, A is highest
    tracker.removedService(refC, refC);
    wrapper.customize(null, null, null);
    assertEquals(1, result.size());
    assertEquals("A", result.get(0));
    result.clear();
    // remove A, no customizer
    tracker.removedService(refA, refA);
    wrapper.customize(null, null, null);
    assertTrue(result.isEmpty());
}

@Test
public void testTrackerCreateFailures() throws Exception {
    final BundleContext bc = mock(BundleContext.class);
    final CustomizerWrapper wrapper = new CustomizerWrapper();
    final List<String> result = new ArrayList<>();
    final LoadBalancerCustomizerFactoryTracker tracker = new LoadBalancerCustomizerFactoryTracker(bc, wrapper);
    wrapper.customize(null, null, null);
    assertTrue(result.isEmpty());
    final ServiceReference<LoadBalancerCustomizerFactory> refA = create(bc, result, 5, "A");
    final ServiceReference<LoadBalancerCustomizerFactory> refB = create(bc, result, 15, null);
    final ServiceReference<LoadBalancerCustomizerFactory> refC = create(bc, result, 25, "C");
    // add A, C, B - C is highest
    tracker.addingService(refA);
    tracker.addingService(refC);
    tracker.addingService(refB);
    wrapper.customize(null, null, null);
    assertEquals(1, result.size());
    assertEquals("C", result.get(0));
    result.clear();
    // remove C, B returns null, therefore A is used
    tracker.removedService(refC, refC);
    wrapper.customize(null, null, null);
    assertEquals(1, result.size());
    assertEquals("A", result.get(0));
    result.clear();
    // remove A, no wrapper
    tracker.removedService(refA, refA);
    wrapper.customize(null, null, null);
    assertTrue(result.isEmpty());
    // remove B, no wrapper
    tracker.removedService(refB, refB);
    wrapper.customize(null, null, null);
    assertTrue(result.isEmpty());
}

@Test
public void testInvokeRequestLog() throws Exception {
    RequestLogTracker tracker = new RequestLogTracker(context, null);
    RequestLog mockRequestLog = mock(RequestLog.class);
    ServiceReference<RequestLog> mockSvcRef = mock(ServiceReference.class);
    when(context.getService(mockSvcRef)).thenReturn(mockRequestLog);
    // These invocations not passed through to the mock because it is not registered yet
    for (int i = 0; i < 10; i++) tracker.log(null, null);
    tracker.addingService(mockSvcRef);
    // These will pass through
    for (int i = 0; i < 15; i++) tracker.log(null, null);
    tracker.removedService(mockSvcRef, mockRequestLog);
    // And these will not.
    for (int i = 0; i < 50; i++) tracker.log(null, null);
    verify(mockRequestLog, times(15)).log(isNull(Request.class), isNull(Response.class));
}

@Test
public void testNaughtyService() throws Exception {
    RequestLogTracker tracker = new RequestLogTracker(context, null);
    AtomicInteger counter = new AtomicInteger(0);
    RequestLog mockRequestLog = new RequestLog() {

        @Override
        public void log(Request request, Response response) {
            counter.addAndGet(1);
            throw new RuntimeException("This service always explodes");
        }
    };
    ServiceReference<RequestLog> mockSvcRef = mock(ServiceReference.class);
    Bundle mockBundle = mock(Bundle.class);
    when(mockSvcRef.getBundle()).thenReturn(mockBundle);
    when(mockBundle.getSymbolicName()).thenReturn("org.example");
    when(mockBundle.getVersion()).thenReturn(new Version("1.0.0"));
    when(context.getService(mockSvcRef)).thenReturn(mockRequestLog);
    tracker.addingService(mockSvcRef);
    // Invoke 200 times
    for (int i = 0; i < 200; i++) tracker.log(null, null);
    tracker.removedService(mockSvcRef, mockRequestLog);
    // Invoked 100 times and then removed
    assertEquals(100, counter.get());
}

