        for (int j = 0; j < NUMBER_OF_SYNCHRONOUS_PROVIDERS; j++) {
            sentDonut = m_synchronousProviders[j].sellDonut();
            for (int k = 0; k < NUMBER_OF_QUICK_CONSUMERS; k++) {
