    assertEquals("fs2 grade -2", 2, fs2Grade);
    assertEquals("fss grade size -2", 3, fssGrades.length);
    assertEquals("fss grade[0] -2", 2, fssGrades[0]);
    assertEquals("fss grade[1] -2", 1, fssGrades[1]);
